diff --git a/Code/RDGeneral/StreamOps.h b/Code/RDGeneral/StreamOps.h
index cb53ccbf123..e26bb0e64ec 100644
--- a/Code/RDGeneral/StreamOps.h
+++ b/Code/RDGeneral/StreamOps.h
@@ -145,28 +145,56 @@ inline boost::uint32_t readPackedIntFromStream(std::stringstream &ss) {
   int shift, offset;
   char tmp;
   ss.read(&tmp, sizeof(tmp));
+  if (ss.fail()) {
+    throw std::runtime_error("failed to read from stream");
+  }
+
   val = UCHAR(tmp);
   offset = 0;
   if ((val & 1) == 0) {
     shift = 1;
   } else if ((val & 3) == 1) {
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 8);
     shift = 2;
     offset = (1 << 7);
   } else if ((val & 7) == 3) {
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 8);
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 16);
     shift = 3;
     offset = (1 << 7) + (1 << 14);
   } else {
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 8);
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 16);
     ss.read((char *)&tmp, sizeof(tmp));
+    if (ss.fail()) {
+      throw std::runtime_error("failed to read from stream");
+    }
+
     val |= (UCHAR(tmp) << 24);
     shift = 3;
     offset = (1 << 7) + (1 << 14) + (1 << 21);
@@ -246,6 +274,9 @@ template <typename T>
 void streamRead(std::istream &ss, T &loc) {
   T tloc;
   ss.read((char *)&tloc, sizeof(T));
+  if (ss.fail()) {
+    throw std::runtime_error("failed to read from stream");
+  }
   loc = EndianSwapBytes<LITTLE_ENDIAN_ORDER, HOST_ENDIAN_ORDER>(tloc);
 }

@@ -260,8 +291,14 @@ inline void streamRead(std::istream &ss, std::string &what, int version) {
   RDUNUSED_PARAM(version);
   unsigned int l;
   ss.read((char *)&l, sizeof(l));
+  if (ss.fail()) {
+    throw std::runtime_error("failed to read from stream");
+  }
   char *buff = new char[l];
   ss.read(buff, sizeof(char) * l);
+  if (ss.fail()) {
+    throw std::runtime_error("failed to read from stream");
+  }
   what = std::string(buff, l);
   delete[] buff;
 };
